section.script:
(function(){
  document.addEventListener('DOMContentLoaded', function(){
    var leg = document.getElementById('pf-leg'); if(!leg){ return; }
    var state = {prim:1, ate:1, usi:1, carr:1, fin:1, autre:1};
    try{ var s = JSON.parse(localStorage.getItem('pf_grps')||'null'); if(s){ state = s; } }catch(e){}
    function apply(){
      document.querySelectorAll('.pf-col[data-grp]').forEach(function(c){
        c.style.display = state[c.getAttribute('data-grp')] ? '' : 'none';
      });
      leg.querySelectorAll('button[data-grp]').forEach(function(b){
        var on = state[b.getAttribute('data-grp')];
        b.style.opacity = on ? '1' : '.35';
        b.style.borderColor = on ? '#0f172a' : 'transparent';
      });
      try{ localStorage.setItem('pf_grps', JSON.stringify(state)); }catch(e){}
    }
    leg.querySelectorAll('button[data-grp]').forEach(function(b){
      b.addEventListener('click', function(){
        var g = b.getAttribute('data-grp');
        state[g] = state[g] ? 0 : 1;
        apply();
      });
    });
    apply();
  });
})();

// 
(function () {
  var DAY = document.getElementById('pf-day').value;
  var WSTART = 6 * 60; // début atelier en minutes UTC (06:00 UTC = 08:00 Paris)
  try { if (sessionStorage.getItem('pf_reseq')) { sessionStorage.removeItem('pf_reseq'); setTimeout(function () { toast('Heures réétalées ✓'); }, 300); } } catch (e) {}

  function rpcWrite(woId, vals, cb) {
    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {
        model: 'mrp.workorder', method: 'write',
        args: [[woId], vals], kwargs: {}
      }})
    }).then(function (r) { return r.json(); }).then(function (data) {
      if (data.error) { cb(false, data.error.data && data.error.data.message || data.error.message); }
      else { cb(true); }
    }).catch(function (e) { cb(false, String(e)); });
  }

  function rpcCall(model, method, args, cb) {
    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { model: model, method: method, args: args, kwargs: {} } })
    }).then(function (r) { return r.json(); }).then(function (data) {
      if (data.error) { cb(false, data.error.data && data.error.data.message || data.error.message); }
      else { cb(true, data.result); }
    }).catch(function (e) { cb(false, String(e)); });
  }

  window.reseq = function (wcId) {
    var col = document.querySelector('.pf-col[data-wc="' + wcId + '"]');
    if (!col) { return; }
    var cards = Array.prototype.slice.call(col.querySelectorAll('.pf-card'));
    var p = DAY.split('-');
    var base = Date.UTC(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]), 0, 0, 0);
    var startMin = WSTART, i = 0;
    function step() {
      if (i >= cards.length) { try { sessionStorage.setItem('pf_reseq', '1'); } catch (e) {} window.location.reload(); return; }
      var card = cards[i]; i++;
      if (card.getAttribute('data-lock') === '1') { step(); return; }
      var dur = parseFloat(card.getAttribute('data-dur')) || 60;
      var woId = parseInt(card.getAttribute('data-id'));
      var s = base + startMin * 60000;
      startMin += dur;
      rpcWrite(woId, { date_start: fmtUTC(s), date_finished: fmtUTC(s + dur * 60000) }, function (ok, msg) { if (!ok) { alert('Échec re-séquencement : ' + msg); } step(); });
    }
    step();
  }

  function fmtUTC(ms) {
    var d = new Date(ms);
    function z(n) { return (n < 10 ? '0' : '') + n; }
    return d.getUTCFullYear() + '-' + z(d.getUTCMonth() + 1) + '-' + z(d.getUTCDate()) + ' ' + z(d.getUTCHours()) + ':' + z(d.getUTCMinutes()) + ':' + z(d.getUTCSeconds());
  }

  function toast(txt) {
    var t = document.createElement('div');
    t.textContent = txt;
    t.style.cssText = 'position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:#2d6a6f;color:#fff;padding:8px 16px;border-radius:8px;z-index:999;font-size:13px;box-shadow:0 4px 12px rgba(0,0,0,.3);';
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 4500);
  }

  // Opérateur (employee_assigned_ids)
  var tpl = document.getElementById('pf-emp-tpl');
  function markOp(sel) { if (sel && !sel.value) { sel.style.border = '2px solid #D33'; sel.style.background = '#FFF0F0'; } else if (sel) { sel.style.border = '2px solid #2E9E5B'; sel.style.background = ''; } }
  document.querySelectorAll('select.pf-op').forEach(function (sel) {
    sel.innerHTML = tpl.innerHTML;
    sel.value = sel.getAttribute('data-op') || '';
    markOp(sel);
    sel.addEventListener('click', function (ev) { ev.preventDefault(); ev.stopPropagation(); });
    sel.addEventListener('change', function () {
      var woId = parseInt(sel.closest('.pf-card').getAttribute('data-id'));
      var v = sel.value;
      var vals = { employee_assigned_ids: v ? [[6, false, [parseInt(v)]]] : [[5]] };
      rpcWrite(woId, vals, function (ok, msg) {
        markOp(sel);
        if (!ok) alert('Échec affectation opérateur : ' + msg);
      });
    });
  });

  // Pastille ✓ = terminer l'ordre de travail
  document.querySelectorAll('.pf-done').forEach(function (b) {
    b.addEventListener('click', function (ev) {
      ev.preventDefault(); ev.stopPropagation();
      if (!confirm('Terminer cette opération ?')) { return; }
      var woId = parseInt(b.closest('.pf-card').getAttribute('data-id'));
      fetch('/web/dataset/call_kw', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { model: 'mrp.workorder', method: 'button_finish', args: [[woId]], kwargs: {} } })
      }).then(function (r) { return r.json(); }).then(function (d) {
        if (d.error) { alert('Échec : ' + (d.error.data && d.error.data.message || d.error.message)); }
        else { window.location.reload(); }
      }).catch(function (e) { alert('Échec : ' + e); });
    });
  });

  // Clic sur le n° de commande = filtre toggle
  var bcEls = document.querySelectorAll('.pf-bc');
  for (var bi = 0; bi < bcEls.length; bi++) {
    (function (el) {
      el.addEventListener('click', function (ev) {
        ev.preventDefault(); ev.stopPropagation();
        var u = new URL(window.location);
        var v = el.getAttribute('data-bc');
        if (u.searchParams.get('bc') === v) { u.searchParams.delete('bc'); } else { u.searchParams.set('bc', v); }
        window.location.href = u.toString();
      });
    })(bcEls[bi]);
  }

  // ----- Déplacement : drag souris (PC) + tap-tap (tactile) -----
  var selected = null, bar = null, dragged = null;

  function clearSel() {
    if (selected) { selected.style.boxShadow = ''; selected = null; }
    if (bar) { bar.parentNode && bar.parentNode.removeChild(bar); bar = null; }
    var cols = document.querySelectorAll('.pf-col');
    for (var i = 0; i < cols.length; i++) { cols[i].style.outline = ''; }
  }

  function applyDrop(card, col) {
    var wcId = parseInt(col.getAttribute('data-wc'));
    if (!(wcId > 0)) { var uprod = parseInt(card.getAttribute('data-prod')); if (!(uprod > 0)) { toast('OF introuvable, impossible de déplanifier.'); clearSel(); return; } if (!confirm('Déplanifier tout l’OF ? Toutes ses opérations repasseront en « À planifier ».')) { clearSel(); return; } rpcCall('mrp.production', 'button_unplan', [[uprod]], function (ok, msg) { if (!ok) { alert('Échec déplanification : ' + msg); clearSel(); } else { window.location.reload(); } }); return; }
    var opSel = card.querySelector('.pf-op');
    if (opSel && !opSel.value) { alert("Veuillez d'abord affecter un opérateur à cette opération."); markOp(opSel); try { opSel.focus(); } catch (e) {} clearSel(); return; }
    var woId = parseInt(card.getAttribute('data-id'));
    var dur = parseFloat(card.getAttribute('data-dur')) || 60;
    var p = DAY.split('-');
    var startMin = WSTART;
    col.querySelectorAll('.pf-card').forEach(function (c) { if (c !== card) { var e = parseInt(c.getAttribute('data-endmin')); if (!isNaN(e) && e > startMin) { startMin = e; } } });
    var startMs = Date.UTC(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]), 0, 0, 0) + startMin * 60000;
    var vals = { workcenter_id: wcId, date_start: fmtUTC(startMs), date_finished: fmtUTC(startMs + dur * 60000) };
    var isDraft = card.getAttribute('data-draft') === '1';
    var prodId = parseInt(card.getAttribute('data-prod'));
    var origin = card.parentNode;
    col.appendChild(card);
    clearSel();
    function doWrite() {
      rpcWrite(woId, vals, function (ok, msg) {
        if (!ok) { origin.appendChild(card); alert('Échec : ' + msg); }
        else { card.setAttribute('data-endmin', String(Math.round(startMin + dur))); if (isDraft) { toast('OF validé et planifié ✓'); setTimeout(function () { window.location.reload(); }, 700); } }
      });
    }
    if (isDraft && prodId > 0) {
      rpcCall('mrp.production', 'action_confirm', [[prodId]], function (ok, msg) {
        if (!ok) { origin.appendChild(card); alert('Échec validation OF : ' + msg); } else { doWrite(); }
      });
    } else { doWrite(); }
  }

  function selectCard(card) {
    clearSel();
    selected = card;
    card.style.boxShadow = '0 0 0 3px #3B82F6';
    var cols = document.querySelectorAll('.pf-col');
    for (var i = 0; i < cols.length; i++) {
      if (parseInt(cols[i].getAttribute('data-wc')) > 0) { cols[i].style.outline = '2px dashed #3B82F6'; }
    }
    bar = document.createElement('div');
    bar.style.cssText = 'position:fixed;bottom:0;left:0;right:0;background:#1F2937;color:#fff;padding:12px 16px;z-index:998;font-size:15px;display:flex;justify-content:space-between;align-items:center;gap:10px;';
    var span = document.createElement('span');
    span.textContent = 'Touchez une machine pour y déplacer cette opération';
    var btn = document.createElement('button');
    btn.textContent = 'Annuler';
    btn.className = 'btn btn-sm btn-outline-light';
    btn.addEventListener('click', clearSel);
    bar.appendChild(span); bar.appendChild(btn);
    document.body.appendChild(bar);
  }

  function valsForTarget(tid, card) {
    var dur = parseFloat(card.getAttribute('data-dur')) || 60;
    var p = DAY.split('-');
    var startMin = WSTART;
    var tcol = document.querySelector('.pf-col[data-wc="' + tid + '"]');
    if (tcol) { tcol.querySelectorAll('.pf-card').forEach(function (c) { if (c !== card) { var e = parseInt(c.getAttribute('data-endmin')); if (!isNaN(e) && e > startMin) { startMin = e; } } }); }
    var s = Date.UTC(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]), 0, 0, 0) + startMin * 60000;
    return { workcenter_id: tid, date_start: fmtUTC(s), date_finished: fmtUTC(s + dur * 60000) };
  }
  var sheet = null;
  function closeSheet() { if (sheet) { sheet.parentNode && sheet.parentNode.removeChild(sheet); sheet = null; } }
  function openSheet(card) {
    var opSel = card.querySelector('.pf-op');
    if (opSel && !opSel.value) { alert("Veuillez d'abord affecter un opérateur à cette opération."); markOp(opSel); return; }
    closeSheet();
    sheet = document.createElement('div');
    sheet.style.cssText = 'position:fixed;left:0;right:0;bottom:0;background:#1F2937;color:#fff;z-index:999;padding:12px;max-height:65vh;overflow:auto;border-radius:12px 12px 0 0;box-shadow:0 -4px 16px rgba(0,0,0,.4);';
    var h = document.createElement('div');
    h.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;';
    var ttl = document.createElement('strong'); ttl.textContent = 'Déplacer vers quelle machine ?';
    var x = document.createElement('button'); x.textContent = 'Annuler'; x.className = 'btn btn-sm btn-outline-light';
    x.addEventListener('click', closeSheet);
    h.appendChild(ttl); h.appendChild(x); sheet.appendChild(h);
    var grid = document.createElement('div');
    grid.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:8px;';
    var tgts = document.querySelectorAll('.pf-target');
    for (var i = 0; i < tgts.length; i++) {
      (function (t) {
        var b = document.createElement('button');
        b.className = 'btn btn-light'; b.style.cssText = 'font-size:13px;padding:10px 6px;';
        b.textContent = t.textContent;
        b.addEventListener('click', function () {
          var woId = parseInt(card.getAttribute('data-id'));
          var isDraft = card.getAttribute('data-draft') === '1';
          var prodId = parseInt(card.getAttribute('data-prod'));
          var vals = valsForTarget(parseInt(t.getAttribute('data-tid')), card);
          function w2() { rpcWrite(woId, vals, function (ok, msg) { if (ok) { window.location.reload(); } else { alert('Échec : ' + msg); } }); }
          if (isDraft && prodId > 0) { rpcCall('mrp.production', 'action_confirm', [[prodId]], function (ok, msg) { if (ok) { w2(); } else { alert('Échec validation OF : ' + msg); } }); } else { w2(); }
          closeSheet();
        });
        grid.appendChild(b);
      })(tgts[i]);
    }
    sheet.appendChild(grid);
    document.body.appendChild(sheet);
  }

  var cards = document.querySelectorAll('.pf-card');
  for (var ci = 0; ci < cards.length; ci++) {
    (function (card) {
      // tap-tap (tactile et souris)
      card.addEventListener('click', function (ev) {
        if (ev.target.closest('a') || ev.target.closest('select')) { return; }
        ev.stopPropagation();
        if (card.getAttribute('data-lock') !== '0') { return; }
        if (window.innerWidth < 768) { openSheet(card); } else if (selected === card) { clearSel(); } else { selectCard(card); }
      });
      // drag souris (PC)
      if (card.getAttribute('data-lock') === '0') {
        card.setAttribute('draggable', 'true');
        card.addEventListener('dragstart', function () { dragged = card; card.style.opacity = '0.4'; });
        card.addEventListener('dragend', function () { card.style.opacity = '1'; });
      }
    })(cards[ci]);
  }

  var cols = document.querySelectorAll('.pf-col');
  for (var co = 0; co < cols.length; co++) {
    (function (col) {
      col.addEventListener('click', function () {
        if (selected) { applyDrop(selected, col); }
      });
      col.addEventListener('dragover', function (ev) { ev.preventDefault(); col.style.boxShadow = 'inset 0 0 0 2px #3B82F6'; });
      col.addEventListener('dragleave', function () { col.style.boxShadow = ''; });
      col.addEventListener('drop', function (ev) {
        ev.preventDefault(); col.style.boxShadow = '';
        if (dragged) { applyDrop(dragged, col); dragged = null; }
      });
    })(cols[co]);
  }

  // Hauteur du board = hauteur restante de la fenêtre (les en-têtes sticky collent dans cette zone)
  function sizeBoard() {
    var el = document.getElementById('pf-board');
    if (!el) { return; }
    var r = el.getBoundingClientRect();
    var h = window.innerHeight - r.top - 8;
    if (h > 200) { el.style.height = h + 'px'; }
  }
  sizeBoard();
  window.addEventListener('resize', sizeBoard);

  // Pansement kiosque : auto-fermer le popup d'erreur BlogPostLink (vieux navigateurs sans :has)
  setInterval(function () {
    var modals = document.querySelectorAll('.modal, .o_dialog');
    for (var i = 0; i < modals.length; i++) {
      if ((modals[i].textContent || '').indexOf('Could not start interaction') !== -1) {
        var btns = modals[i].querySelectorAll('button');
        for (var j = 0; j < btns.length; j++) {
          if (/fermer|close/i.test(btns[j].textContent || '')) { btns[j].click(); }
        }
      }
    }
  }, 1200);
})();
//
